//! Checks colour deconvolution against QuPath's own output.
//!
//! Fixtures generated by `parity/java/ColourDeconvolution.java`:
//! `ColourDeconvolution.json` via `./parity/record.sh` (synthetic, no slide),
//! and `ColourDeconvolutionTile.json` via `./parity/record-slide.sh` (a real
//! tile, which needs one).
//!
//! Recorded through `ColorTransformer.getTransformedPixels`, the call
//! `IJTools.colorDeconvolve` makes for `WatershedCellDetection` — so this pins
//! the path QuPath actually runs, including its 8-bit optical-density lookup
//! table, and not a re-derivation of Ruifrok and Johnston's formula.
//!
//! This fixture found a real bug on its first run: the eosin constant was the
//! **DAB** vector, so the pipeline had been performing H-DAB deconvolution
//! under the name H&E. Nothing downstream could have noticed. The output was a
//! smooth, plausible single-channel image the whole time — which is why both
//! stain sets are recorded here, and why the matrix is compared as well as the
//! pixels.

use std::path::{Path, PathBuf};

use qupath_pipeline::Stains;

/// Relative tolerance for a deconvolved value, per `parity/README.md`.
///
/// Both sides accumulate in `f64` over an exact-per-byte optical density and
/// narrow to `f32` once at the end, so the agreement is far tighter than this
/// in practice; the assertions below report the worst seen.
const TOLERANCE: f64 = 1e-5;

/// Values below this are compared absolutely rather than relatively.
///
/// A deconvolved value passes through zero — that is what the background is —
/// and relative error is unbounded there for reasons that say nothing about
/// correctness. `f32` carries about seven significant digits, and the largest
/// values here are of order 1, so this is the noise floor of the output type.
const NEAR_ZERO: f64 = 1e-6;

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures")
        .join(name)
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

fn numbers(text: &str) -> Vec<f64> {
    text.split(',')
        .map(|v| v.trim().parse().expect("number"))
        .collect()
}

/// One recorded stain set: the matrix QuPath built and the pixels it produced.
struct Case {
    name: String,
    /// QuPath's `getMatrixInverse()`, indexed `[channel][stain]`.
    inverse: [[f64; 3]; 3],
    max_values: [f64; 3],
    /// Packed 24-bit RGB, as QuPath was handed it.
    rgb: Vec<u32>,
    /// Three channels of deconvolved output, one per stain.
    stains: [Vec<f64>; 3],
}

fn parse_case(text: &str, name: &str) -> Case {
    let key = format!("\"{name}\": {{");
    let at = text
        .find(&key)
        .unwrap_or_else(|| panic!("{name} in fixture"))
        + key.len();

    let (inverse_text, at) = between(text, "\"inverse\": [[", "]]", at);
    let flat = numbers(&inverse_text.replace("], [", ", "));
    let mut inverse = [[0.0f64; 3]; 3];
    for (index, value) in flat.iter().enumerate() {
        inverse[index / 3][index % 3] = *value;
    }

    let (max_text, at) = between(text, "\"maxValues\": [", "]", at);
    let max_flat = numbers(max_text);
    let max_values = [max_flat[0], max_flat[1], max_flat[2]];

    let (rgb_text, mut at) = between(text, "\"rgbIn\": [", "]", at);
    let rgb: Vec<u32> = rgb_text
        .split(',')
        .map(|v| v.trim().parse().expect("rgb"))
        .collect();

    let stains = std::array::from_fn(|s| {
        let key = format!("\"stain{}\": [", s + 1);
        let (values, next) = between(text, &key, "]", at);
        at = next;
        numbers(values)
    });

    Case {
        name: name.to_owned(),
        inverse,
        max_values,
        rgb,
        stains,
    }
}

/// Compares one recorded stain set against the Rust implementation.
///
/// Prints the worst relative difference seen, so a passing run still says how
/// much of the tolerance was used rather than only that it passed — a margin
/// that quietly erodes towards the limit is worth seeing before it fails.
fn check(case: &Case, stains: &Stains) {
    // The matrix first. When the pixels disagree this is what says why: a wrong
    // constant moves the matrix, while a wrong optical density or a wrong
    // transpose leaves it intact.
    let mine = stains.coefficients();
    for (channel, row) in case.inverse.iter().enumerate() {
        for (stain, &theirs) in row.iter().enumerate() {
            // QuPath indexes [channel][stain]; `coefficients` is the transpose,
            // so this comparison is also what pins that convention.
            let ours = mine[stain][channel];
            assert!(
                (ours - theirs).abs() <= 1e-9,
                "{}: matrix[{channel}][{stain}] is {ours}, QuPath has {theirs}",
                case.name
            );
        }
    }

    assert_eq!(
        case.max_values,
        [255.0, 255.0, 255.0],
        "{}: fixture uses a non-default white point; \
         Stains::from_two would be needed to reproduce it",
        case.name
    );

    let mut worst = 0.0f64;
    let mut worst_at = (0usize, 0usize);
    for (stain_index, expected) in case.stains.iter().enumerate() {
        assert_eq!(
            expected.len(),
            case.rgb.len(),
            "{}: stain {stain_index} has {} values for {} pixels",
            case.name,
            expected.len(),
            case.rgb.len()
        );

        for (pixel, (&packed, &theirs)) in case.rgb.iter().zip(expected).enumerate() {
            let red = ((packed >> 16) & 0xff) as u8;
            let green = ((packed >> 8) & 0xff) as u8;
            let blue = (packed & 0xff) as u8;

            let ours = f64::from(stains.stain(stain_index, red, green, blue));
            let difference = (ours - theirs).abs();
            let relative = if theirs.abs() > NEAR_ZERO {
                difference / theirs.abs()
            } else {
                difference
            };

            assert!(
                relative <= TOLERANCE,
                "{}: stain {stain_index} at rgb({red}, {green}, {blue}) \
                 gave {ours}, QuPath gave {theirs} (relative {relative:.3e})",
                case.name
            );
            if relative > worst {
                worst = relative;
                worst_at = (stain_index, pixel);
            }
        }
    }

    println!(
        "{:>6}  {} pixels x 3 stains  worst relative {worst:.3e} at stain {}, pixel {}",
        case.name,
        case.rgb.len(),
        worst_at.0,
        worst_at.1
    );
}

#[test]
fn matches_qupath_colour_deconvolution() {
    let path = fixture("ColourDeconvolution.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));

    // Both stain sets, because they share a haematoxylin vector and differ only
    // in the second. Checking one alone is what let the DAB-as-eosin bug stand.
    check(&parse_case(&text, "H&E"), &Stains::h_and_e());
    check(&parse_case(&text, "H-DAB"), &Stains::h_dab());
}

#[test]
fn matches_qupath_on_a_real_tile() {
    // A synthetic sweep sends every channel across its whole range
    // independently. Real tissue does not: its channels are correlated and sit
    // in a narrow bright band, which is where the deconvolution's cancellation
    // is worst and where any residual error would actually bite.
    let path = fixture("ColourDeconvolutionTile.json");
    let Ok(text) = std::fs::read_to_string(&path) else {
        // Slides are untracked because they are hundreds of megabytes, so this
        // is skipped rather than failed where they are absent. It runs in any
        // checkout that has followed docs/test-data.md.
        eprintln!("skipping: {} not recorded", path.display());
        return;
    };
    check(&parse_case(&text, "tile"), &Stains::h_and_e());
}
